<?php require_once 'config.php';require_role(['admin']);$pdo=db();$tables=[['users'],['settings'],['accounts'],['categories'],['account_openings'],['transactions'],['monthly_inventories'],['audit_logs']];header('Content-Type: application/sql; charset=utf-8');header('Content-Disposition: attachment; filename="eglise_germe_de_david_backup_'.date('Ymd_His').'.sql"');echo "SET FOREIGN_KEY_CHECKS=0;\n";foreach($tables as $t){$name=$t[0];$create=$pdo->query('SHOW CREATE TABLE `'.$name.'`')->fetch(PDO::FETCH_NUM);echo "DROP TABLE IF EXISTS `$name`;\n".$create[1].";\n";$rows=$pdo->query('SELECT * FROM `'.$name.'`');while($r=$rows->fetch(PDO::FETCH_ASSOC)){$vals=[];foreach($r as $v)$vals[]=$v===null?'NULL':$pdo->quote((string)$v);echo 'INSERT INTO `'.$name.'` VALUES('.implode(',',$vals).");\n";}}echo "SET FOREIGN_KEY_CHECKS=1;\n";